20	import {subPixelOptimize} from '../../util/graphic';
21	import createRenderPlanner from '../helper/createRenderPlanner';
22	import {parsePercent} from '../../util/number';
23	import {map, retrieve2} from 'zrender/src/core/util';
24	import { DimensionIndex, StageHandler, StageHandlerProgressParams } from '../../util/types';
25	import CandlestickSeriesModel, { CandlestickDataItemOption } from './CandlestickSeries';
26	import SeriesData from '../../data/SeriesData';
27	import { RectLike } from 'zrender/src/core/BoundingRect';
28	import DataStore from '../../data/DataStore';
29	import { createFloat32Array } from '../../util/vendor';
30	
31	export interface CandlestickItemLayout {
32	    sign: number
33	    initBaseline: number
34	    ends: number[][]
35	    brushRect: RectLike
36	}
37	
38	export interface CandlestickLayoutMeta {
39	    candleWidth: number
40	    isSimpleBox: boolean
41	}
42	
43	const candlestickLayout: StageHandler = {
44	
45	    seriesType: 'candlestick',
46	
47	    plan: createRenderPlanner(),
48	
49	    reset: function (seriesModel: CandlestickSeriesModel) {
50	
51	        const coordSys = seriesModel.coordinateSystem;
52	        const data = seriesModel.getData();
53	        const candleWidth = calculateCandleWidth(seriesModel, data);
54	        const cDimIdx = 0;
55	        const vDimIdx = 1;
56	        const coordDims = ['x', 'y'];
57	        const cDimI = data.getDimensionIndex(data.mapDimension(coordDims[cDimIdx]));
58	        const vDimsI = map(data.mapDimensionsAll(coordDims[vDimIdx]), data.getDimensionIndex, data);
59	        const openDimI = vDimsI[0];
60	        const closeDimI = vDimsI[1];
61	        const lowestDimI = vDimsI[2];
62	        const highestDimI = vDimsI[3];
63	
64	        data.setLayout({
65	            candleWidth: candleWidth,
66	            // The value is experimented visually.
67	            isSimpleBox: candleWidth <= 1.3
68	        } as CandlestickLayoutMeta);
69	
70	        if (cDimI < 0 || vDimsI.length < 4) {
71	            return;
72	        }
73	
74	        return {
75	            progress: seriesModel.pipelineContext.large
76	                ? largeProgress : normalProgress
77	        };
78	
79	        function normalProgress(params: StageHandlerProgressParams, data: SeriesData) {
80	            let dataIndex;
81	            const store = data.getStore();
82	            while ((dataIndex = params.next()) != null) {
83	
84	                const axisDimVal = store.get(cDimI, dataIndex) as number;
85	                const openVal = store.get(openDimI, dataIndex) as number;
86	                const closeVal = store.get(closeDimI, dataIndex) as number;
87	                const lowestVal = store.get(lowestDimI, dataIndex) as number;
88	                const highestVal = store.get(highestDimI, dataIndex) as number;
89	
90	                const ocLow = Math.min(openVal, closeVal);
91	                const ocHigh = Math.max(openVal, closeVal);
92	
93	                const ocLowPoint = getPoint(ocLow, axisDimVal);
94	                const ocHighPoint = getPoint(ocHigh, axisDimVal);
95	                const lowestPoint = getPoint(lowestVal, axisDimVal);
96	                const highestPoint = getPoint(highestVal, axisDimVal);
97	
98	                const ends: number[][] = [];
99	                addBodyEnd(ends, ocHighPoint, 0);
100	                addBodyEnd(ends, ocLowPoint, 1);
101	
102	                ends.push(
103	                    subPixelOptimizePoint(highestPoint),
104	                    subPixelOptimizePoint(ocHighPoint),
105	                    subPixelOptimizePoint(lowestPoint),
106	                    subPixelOptimizePoint(ocLowPoint)
107	                );
108	
109	                const itemModel = data.getItemModel<CandlestickDataItemOption>(dataIndex);
110	                const hasDojiColor = !!itemModel.get(['itemStyle', 'borderColorDoji']);
111	                data.setItemLayout(dataIndex, {
112	                    sign: getSign(store, dataIndex, openVal, closeVal, closeDimI, hasDojiColor),
113	                    initBaseline: openVal > closeVal
114	                        ? ocHighPoint[vDimIdx] : ocLowPoint[vDimIdx], // open point.
115	                    ends: ends,
116	                    brushRect: makeBrushRect(lowestVal, highestVal, axisDimVal)
117	                } as CandlestickItemLayout);
118	            }
119	
120	            function getPoint(val: number, axisDimVal: number) {
121	                const p = [];
122	                p[cDimIdx] = axisDimVal;
123	                p[vDimIdx] = val;
124	                return (isNaN(axisDimVal) || isNaN(val))
125	                    ? [NaN, NaN]
126	                    : coordSys.dataToPoint(p);
127	            }
128	
129	            function addBodyEnd(ends: number[][], point: number[], start: number) {
130	                const point1 = point.slice();
131	                const point2 = point.slice();
132	
133	                point1[cDimIdx] = subPixelOptimize(
134	                    point1[cDimIdx] + candleWidth / 2, 1, false
135	                );
136	                point2[cDimIdx] = subPixelOptimize(
137	                    point2[cDimIdx] - candleWidth / 2, 1, true
138	                );
139	
140	                start
141	                    ? ends.push(point1, point2)
142	                    : ends.push(point2, point1);
143	            }
144	
145	            function makeBrushRect(lowestVal: number, highestVal: number, axisDimVal: number) {
146	                const pmin = getPoint(lowestVal, axisDimVal);
147	                const pmax = getPoint(highestVal, axisDimVal);
148	
149	                pmin[cDimIdx] -= candleWidth / 2;
150	                pmax[cDimIdx] -= candleWidth / 2;
151	
152	                return {
153	                    x: pmin[0],
154	                    y: pmin[1],
155	                    width: vDimIdx ? candleWidth : pmax[0] - pmin[0],
156	                    height: vDimIdx ? pmax[1] - pmin[1] : candleWidth
157	                };
158	            }
159	
160	            function subPixelOptimizePoint(point: number[]) {
161	                point[cDimIdx] = subPixelOptimize(point[cDimIdx], 1);
162	                return point;
163	            }
164	        }
165	
166	        function largeProgress(params: StageHandlerProgressParams, data: SeriesData) {
167	            // Structure: [sign, x, yhigh, ylow, sign, x, yhigh, ylow, ...]
168	            const points = createFloat32Array(params.count * 4);
169	            let offset = 0;
170	            let point;
171	            const tmpIn: number[] = [];
172	            const tmpOut: number[] = [];
173	            let dataIndex;
174	            const store = data.getStore();
175	            const hasDojiColor = !!seriesModel.get(['itemStyle', 'borderColorDoji']);
176	
177	            while ((dataIndex = params.next()) != null) {
178	                const axisDimVal = store.get(cDimI, dataIndex) as number;
179	                const openVal = store.get(openDimI, dataIndex) as number;
180	                const closeVal = store.get(closeDimI, dataIndex) as number;
181	                const lowestVal = store.get(lowestDimI, dataIndex) as number;
182	                const highestVal = store.get(highestDimI, dataIndex) as number;
183	
184	                if (isNaN(axisDimVal) || isNaN(lowestVal) || isNaN(highestVal)) {
185	                    points[offset++] = NaN;
186	                    offset += 3;
187	                    continue;
188	                }
189	
190	                points[offset++] = getSign(store, dataIndex, openVal, closeVal, closeDimI, hasDojiColor);
191	
192	                tmpIn[cDimIdx] = axisDimVal;
193	
194	                tmpIn[vDimIdx] = lowestVal;
195	                point = coordSys.dataToPoint(tmpIn, null, tmpOut);
196	                points[offset++] = point ? point[0] : NaN;
197	                points[offset++] = point ? point[1] : NaN;
198	                tmpIn[vDimIdx] = highestVal;
199	                point = coordSys.dataToPoint(tmpIn, null, tmpOut);
200	                points[offset++] = point ? point[1] : NaN;
201	            }
202	
203	            data.setLayout('largePoints', points);
204	        }
205	    }
206	};
207	
208	/**
209	 * Get the sign of a single data.
210	 *
211	 * @returns 0 for doji with hasDojiColor: true,
212	 *          1 for positive,
213	 *          -1 for negative.
214	 */
215	function getSign(
216	    store: DataStore, dataIndex: number, openVal: number, closeVal: number, closeDimI: DimensionIndex,
217	    hasDojiColor: boolean
218	): -1 | 1 | 0 {
219	    let sign: -1 | 1 | 0;
220	    if (openVal > closeVal) {
221	        sign = -1;
222	    }
223	    else if (openVal < closeVal) {
224	        sign = 1;
225	    }
226	    else {
227	        sign = hasDojiColor
228	            // When doji color is set, use it instead of color/color0.
229	            ? 0
230	            : (dataIndex > 0
231	                // If close === open, compare with close of last record
232	                ? (store.get(closeDimI, dataIndex - 1) <= closeVal ? 1 : -1)
233	                // No record of previous, set to be positive
234	                : 1
235	            );
236	    }
237	
238	    return sign;
239	}
240	
241	function calculateCandleWidth(seriesModel: CandlestickSeriesModel, data: SeriesData) {
242	    const baseAxis = seriesModel.getBaseAxis();
243	    let extent;
244	
245	    const bandWidth = baseAxis.type === 'category'
246	        ? baseAxis.getBandWidth()
247	        : (
248	            extent = baseAxis.getExtent(),
249	            Math.abs(extent[1] - extent[0]) / data.count()
250	        );
251	
252	    const barMaxWidth = parsePercent(
253	        retrieve2(seriesModel.get('barMaxWidth'), bandWidth),
254	        bandWidth
255	    );
256	    const barMinWidth = parsePercent(
257	        retrieve2(seriesModel.get('barMinWidth'), 1),
258	        bandWidth
259	    );
260	    const barWidth = seriesModel.get('barWidth');
261	
262	    return barWidth != null
263	        ? parsePercent(barWidth, bandWidth)
264	        // Put max outer to ensure bar visible in spite of overlap.
265	        : Math.max(Math.min(bandWidth / 2, barMaxWidth), barMinWidth);
266	}
267	
268	export default candlestickLayout;
