20	import * as zrUtil from 'zrender/src/core/util';
21	import ChartView from '../../view/Chart';
22	import * as graphic from '../../util/graphic';
23	import { setStatesStylesFromModel, toggleHoverEmphasis } from '../../util/states';
24	import Path, { PathProps } from 'zrender/src/graphic/Path';
25	import {createClipPath} from '../helper/createClipPathFromCoordSys';
26	import CandlestickSeriesModel, { CandlestickDataItemOption } from './CandlestickSeries';
27	import GlobalModel from '../../model/Global';
28	import ExtensionAPI from '../../core/ExtensionAPI';
29	import { StageHandlerProgressParams } from '../../util/types';
30	import SeriesData from '../../data/SeriesData';
31	import {CandlestickItemLayout} from './candlestickLayout';
32	import { CoordinateSystemClipArea } from '../../coord/CoordinateSystem';
33	import Model from '../../model/Model';
34	import { saveOldStyle } from '../../animation/basicTransition';
35	import Element from 'zrender/src/Element';
36	import { getBorderColor, getColor } from './candlestickVisual';
37	
38	const SKIP_PROPS = ['color', 'borderColor'] as const;
39	
40	class CandlestickView extends ChartView {
41	
42	    static readonly type = 'candlestick';
43	    readonly type = CandlestickView.type;
44	
45	    private _isLargeDraw: boolean;
46	
47	    private _data: SeriesData;
48	
49	    private _progressiveEls: Element[];
50	
51	    render(seriesModel: CandlestickSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
52	        // If there is clipPath created in large mode. Remove it.
53	        this.group.removeClipPath();
54	        // Clear previously rendered progressive elements.
55	        this._progressiveEls = null;
56	
57	        this._updateDrawMode(seriesModel);
58	
59	        this._isLargeDraw
60	            ? this._renderLarge(seriesModel)
61	            : this._renderNormal(seriesModel);
62	    }
63	
64	    incrementalPrepareRender(seriesModel: CandlestickSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
65	        this._clear();
66	        this._updateDrawMode(seriesModel);
67	    }
68	
69	    incrementalRender(
70	        params: StageHandlerProgressParams,
71	        seriesModel: CandlestickSeriesModel,
72	        ecModel: GlobalModel,
73	        api: ExtensionAPI
74	    ) {
75	        this._progressiveEls = [];
76	        this._isLargeDraw
77	             ? this._incrementalRenderLarge(params, seriesModel)
78	             : this._incrementalRenderNormal(params, seriesModel);
79	    }
80	
81	    eachRendered(cb: (el: Element) => boolean | void) {
82	        graphic.traverseElements(this._progressiveEls || this.group, cb);
83	    }
84	
85	    _updateDrawMode(seriesModel: CandlestickSeriesModel) {
86	        const isLargeDraw = seriesModel.pipelineContext.large;
87	        if (this._isLargeDraw == null || isLargeDraw !== this._isLargeDraw) {
88	            this._isLargeDraw = isLargeDraw;
89	            this._clear();
90	        }
91	    }
92	
93	    _renderNormal(seriesModel: CandlestickSeriesModel) {
94	        const data = seriesModel.getData();
95	        const oldData = this._data;
96	        const group = this.group;
97	        const isSimpleBox = data.getLayout('isSimpleBox');
98	
99	        const needsClip = seriesModel.get('clip', true);
100	        const coord = seriesModel.coordinateSystem;
101	        const clipArea = coord.getArea && coord.getArea();
102	
103	        // There is no old data only when first rendering or switching from
104	        // stream mode to normal mode, where previous elements should be removed.
105	        if (!this._data) {
106	            group.removeAll();
107	        }
108	
109	        data.diff(oldData)
110	            .add(function (newIdx) {
111	                if (data.hasValue(newIdx)) {
112	                    const itemLayout = data.getItemLayout(newIdx) as CandlestickItemLayout;
113	
114	                    if (needsClip && isNormalBoxClipped(clipArea, itemLayout)) {
115	                        return;
116	                    }
117	
118	                    const el = createNormalBox(itemLayout, newIdx, true);
119	                    graphic.initProps(el, {shape: {points: itemLayout.ends}}, seriesModel, newIdx);
120	
121	                    setBoxCommon(el, data, newIdx, isSimpleBox);
122	
123	                    group.add(el);
124	
125	                    data.setItemGraphicEl(newIdx, el);
126	                }
127	            })
128	            .update(function (newIdx, oldIdx) {
129	                let el = oldData.getItemGraphicEl(oldIdx) as NormalBoxPath;
130	
131	                // Empty data
132	                if (!data.hasValue(newIdx)) {
133	                    group.remove(el);
134	                    return;
135	                }
136	
137	                const itemLayout = data.getItemLayout(newIdx) as CandlestickItemLayout;
138	                if (needsClip && isNormalBoxClipped(clipArea, itemLayout)) {
139	                    group.remove(el);
140	                    return;
141	                }
142	
143	                if (!el) {
144	                    el = createNormalBox(itemLayout, newIdx);
145	                }
146	                else {
147	                    graphic.updateProps(el, {
148	                        shape: {
149	                            points: itemLayout.ends
150	                        }
151	                    }, seriesModel, newIdx);
152	
153	                    saveOldStyle(el);
154	                }
155	
156	                setBoxCommon(el, data, newIdx, isSimpleBox);
157	
158	                group.add(el);
159	                data.setItemGraphicEl(newIdx, el);
160	            })
161	            .remove(function (oldIdx) {
162	                const el = oldData.getItemGraphicEl(oldIdx);
163	                el && group.remove(el);
164	            })
165	            .execute();
166	
167	        this._data = data;
168	    }
169	
170	    _renderLarge(seriesModel: CandlestickSeriesModel) {
171	        this._clear();
172	
173	        createLarge(seriesModel, this.group);
174	
175	        const clipPath = seriesModel.get('clip', true)
176	            ? createClipPath(seriesModel.coordinateSystem, false, seriesModel)
177	            : null;
178	        if (clipPath) {
179	            this.group.setClipPath(clipPath);
180	        }
181	        else {
182	            this.group.removeClipPath();
183	        }
184	
185	    }
186	
187	    _incrementalRenderNormal(params: StageHandlerProgressParams, seriesModel: CandlestickSeriesModel) {
188	        const data = seriesModel.getData();
189	        const isSimpleBox = data.getLayout('isSimpleBox');
190	
191	        let dataIndex;
192	        while ((dataIndex = params.next()) != null) {
193	            const itemLayout = data.getItemLayout(dataIndex) as CandlestickItemLayout;
194	            const el = createNormalBox(itemLayout, dataIndex);
195	            setBoxCommon(el, data, dataIndex, isSimpleBox);
196	
197	            el.incremental = true;
198	            this.group.add(el);
199	
200	            this._progressiveEls.push(el);
201	        }
202	    }
203	
204	    _incrementalRenderLarge(params: StageHandlerProgressParams, seriesModel: CandlestickSeriesModel) {
205	        createLarge(seriesModel, this.group, this._progressiveEls, true);
206	    }
207	
208	    remove(ecModel: GlobalModel) {
209	        this._clear();
210	    }
211	
212	    _clear() {
213	        this.group.removeAll();
214	        this._data = null;
215	    }
216	}
217	
218	class NormalBoxPathShape {
219	    points: number[][];
220	}
221	
222	interface NormalBoxPathProps extends PathProps {
223	    shape?: Partial<NormalBoxPathShape>
224	}
225	
226	class NormalBoxPath extends Path<NormalBoxPathProps> {
227	
228	    readonly type = 'normalCandlestickBox';
229	
230	    shape: NormalBoxPathShape;
231	
232	    __simpleBox: boolean;
233	
234	    constructor(opts?: NormalBoxPathProps) {
235	        super(opts);
236	    }
237	
238	    getDefaultShape() {
239	        return new NormalBoxPathShape();
240	    }
241	
242	    buildPath(ctx: CanvasRenderingContext2D, shape: NormalBoxPathShape) {
243	        const ends = shape.points;
244	
245	        if (this.__simpleBox) {
246	            ctx.moveTo(ends[4][0], ends[4][1]);
247	            ctx.lineTo(ends[6][0], ends[6][1]);
248	        }
249	        else {
250	            ctx.moveTo(ends[0][0], ends[0][1]);
251	            ctx.lineTo(ends[1][0], ends[1][1]);
252	            ctx.lineTo(ends[2][0], ends[2][1]);
253	            ctx.lineTo(ends[3][0], ends[3][1]);
254	            ctx.closePath();
255	
256	            ctx.moveTo(ends[4][0], ends[4][1]);
257	            ctx.lineTo(ends[5][0], ends[5][1]);
258	            ctx.moveTo(ends[6][0], ends[6][1]);
259	            ctx.lineTo(ends[7][0], ends[7][1]);
260	        }
261	    }
262	}
263	
264	
265	function createNormalBox(itemLayout: CandlestickItemLayout, dataIndex: number, isInit?: boolean) {
266	    const ends = itemLayout.ends;
267	    return new NormalBoxPath({
268	        shape: {
269	            points: isInit
270	                ? transInit(ends, itemLayout)
271	                : ends
272	        },
273	        z2: 100
274	    });
275	}
276	
277	function isNormalBoxClipped(clipArea: CoordinateSystemClipArea, itemLayout: CandlestickItemLayout) {
278	    let clipped = true;
279	    for (let i = 0; i < itemLayout.ends.length; i++) {
280	        // If any point are in the region.
281	        if (clipArea.contain(itemLayout.ends[i][0], itemLayout.ends[i][1])) {
282	            clipped = false;
283	            break;
284	        }
285	    }
286	    return clipped;
287	}
288	
289	function setBoxCommon(el: NormalBoxPath, data: SeriesData, dataIndex: number, isSimpleBox?: boolean) {
290	    const itemModel = data.getItemModel(dataIndex) as Model<CandlestickDataItemOption>;
291	
292	    el.useStyle(data.getItemVisual(dataIndex, 'style'));
293	    el.style.strokeNoScale = true;
294	
295	    el.__simpleBox = isSimpleBox;
296	
297	    setStatesStylesFromModel(el, itemModel);
298	
299	    const sign = data.getItemLayout(dataIndex).sign;
300	    zrUtil.each(el.states, (state, stateName) => {
301	        const stateModel = itemModel.getModel(stateName as any);
302	        const color = getColor(sign, stateModel);
303	        const borderColor = getBorderColor(sign, stateModel) || color;
304	        const stateStyle = state.style || (state.style = {});
305	        color && (stateStyle.fill = color);
306	        borderColor && (stateStyle.stroke = borderColor);
307	    });
308	
309	    const emphasisModel = itemModel.getModel('emphasis');
310	    toggleHoverEmphasis(el, emphasisModel.get('focus'), emphasisModel.get('blurScope'), emphasisModel.get('disabled'));
311	}
312	
313	function transInit(points: number[][], itemLayout: CandlestickItemLayout) {
314	    return zrUtil.map(points, function (point) {
315	        point = point.slice();
316	        point[1] = itemLayout.initBaseline;
317	        return point;
318	    });
319	}
320	
321	
322	
323	class LargeBoxPathShape {
324	    points: ArrayLike<number>;
325	}
326	
327	interface LargeBoxPathProps extends PathProps {
328	    shape?: Partial<LargeBoxPathShape>
329	    __sign?: number
330	}
331	
332	class LargeBoxPath extends Path {
333	    readonly type = 'largeCandlestickBox';
334	
335	    shape: LargeBoxPathShape;
336	
337	    __sign: number;
338	
339	    constructor(opts?: LargeBoxPathProps) {
340	        super(opts);
341	    }
342	
343	    getDefaultShape() {
344	        return new LargeBoxPathShape();
345	    }
346	
347	    buildPath(ctx: CanvasRenderingContext2D, shape: LargeBoxPathShape) {
348	        // Drawing lines is more efficient than drawing
349	        // a whole line or drawing rects.
350	        const points = shape.points;
351	        for (let i = 0; i < points.length;) {
352	            if (this.__sign === points[i++]) {
353	                const x = points[i++];
354	                ctx.moveTo(x, points[i++]);
355	                ctx.lineTo(x, points[i++]);
356	            }
357	            else {
358	                i += 3;
359	            }
360	        }
361	    }
362	}
363	
364	function createLarge(
365	    seriesModel: CandlestickSeriesModel,
366	    group: graphic.Group,
367	    progressiveEls?: Element[],
368	    incremental?: boolean
369	) {
370	    const data = seriesModel.getData();
371	    const largePoints = data.getLayout('largePoints');
372	
373	    const elP = new LargeBoxPath({
374	        shape: {points: largePoints},
375	        __sign: 1,
376	        ignoreCoarsePointer: true
377	    });
378	    group.add(elP);
379	    const elN = new LargeBoxPath({
380	        shape: {points: largePoints},
381	        __sign: -1,
382	        ignoreCoarsePointer: true
383	    });
384	    group.add(elN);
385	    const elDoji = new LargeBoxPath({
386	        shape: {points: largePoints},
387	        __sign: 0,
388	        ignoreCoarsePointer: true
389	    });
390	    group.add(elDoji);
391	
392	    setLargeStyle(1, elP, seriesModel, data);
393	    setLargeStyle(-1, elN, seriesModel, data);
