32	interface CommonOption extends SeriesOption, SeriesOnCartesianOptionMixin {
33	    layout?: LayoutOrient
34	
35	    // data?: (DataItemOption | number[])[]
36	}
37	
38	type WhiskerBoxCommonData = (DataItemOption | number[])[];
39	
40	interface DataItemOption {
41	    value?: number[]
42	}
43	
44	interface WhiskerBoxCommonMixin<Opts extends CommonOption> extends SeriesModel<Opts>{}
45	class WhiskerBoxCommonMixin<Opts extends CommonOption> {
46	
47	    /**
48	     * @private
49	     * @type {string}
50	     */
51	    _baseAxisDim: string;
52	
53	    defaultValueDimensions: CoordDimensionDefinition['dimsDef'];
54	
55	    /**
56	     * @private
57	     */
58	    _hasEncodeRule(key: string) {
59	        const encodeRules = this.getEncode();
60	        return encodeRules && encodeRules.get(key) != null;
61	    }
62	
63	    /**
64	     * @override
65	     */
66	    getInitialData(option: Opts, ecModel: GlobalModel): SeriesData {
67	        // When both types of xAxis and yAxis are 'value', layout is
68	        // needed to be specified by user. Otherwise, layout can be
69	        // judged by which axis is category.
70	
71	        let ordinalMeta;
72	
73	        const xAxisModel = ecModel.getComponent('xAxis', this.get('xAxisIndex')) as CartesianAxisModel;
74	        const yAxisModel = ecModel.getComponent('yAxis', this.get('yAxisIndex')) as CartesianAxisModel;
75	        const xAxisType = xAxisModel.get('type');
76	        const yAxisType = yAxisModel.get('type');
77	        let addOrdinal;
78	
79	        // FIXME
80	        // Consider time axis.
81	
82	        if (xAxisType === 'category') {
83	            option.layout = 'horizontal';
84	            ordinalMeta = xAxisModel.getOrdinalMeta();
85	            addOrdinal = !this._hasEncodeRule('x');
86	        }
87	        else if (yAxisType === 'category') {
88	            option.layout = 'vertical';
89	            ordinalMeta = yAxisModel.getOrdinalMeta();
90	            addOrdinal = !this._hasEncodeRule('y');
91	        }
92	        else {
93	            option.layout = option.layout || 'horizontal';
94	        }
95	
96	        const coordDims = ['x', 'y'];
97	        const baseAxisDimIndex = option.layout === 'horizontal' ? 0 : 1;
98	        const baseAxisDim = this._baseAxisDim = coordDims[baseAxisDimIndex];
99	        const otherAxisDim = coordDims[1 - baseAxisDimIndex];
100	        const axisModels = [xAxisModel, yAxisModel];
101	        const baseAxisType = axisModels[baseAxisDimIndex].get('type');
102	        const otherAxisType = axisModels[1 - baseAxisDimIndex].get('type');
103	        const data = option.data as WhiskerBoxCommonData;
104	
105	        // Clone a new data for next setOption({}) usage.
106	        // Avoid modifying current data will affect further update.
107	        if (data && addOrdinal) {
108	            const newOptionData: WhiskerBoxCommonData = [];
109	            zrUtil.each(data, function (item, index) {
110	                let newItem;
111	                if (zrUtil.isArray(item)) {
112	                    newItem = item.slice();
113	                    // Modify current using data.
114	                    item.unshift(index);
115	                }
116	                else if (zrUtil.isArray(item.value)) {
117	                    newItem = zrUtil.extend({}, item);
118	                    newItem.value = newItem.value.slice();
119	                    // Modify current using data.
120	                    item.value.unshift(index);
121	                }
122	                else {
123	                    newItem = item;
124	                }
125	                newOptionData.push(newItem);
126	            });
127	            option.data = newOptionData;
128	        }
129	
130	        const defaultValueDimensions = this.defaultValueDimensions;
131	        const coordDimensions: CoordDimensionDefinition[] = [{
132	            name: baseAxisDim,
133	            type: getDimensionTypeByAxis(baseAxisType),
134	            ordinalMeta: ordinalMeta,
135	            otherDims: {
136	                tooltip: false,
137	                itemName: 0
138	            },
139	            dimsDef: ['base']
140	        }, {
141	            name: otherAxisDim,
142	            type: getDimensionTypeByAxis(otherAxisType),
143	            dimsDef: defaultValueDimensions.slice()
144	        }];
145	
146	        return createSeriesDataSimply(
147	            this,
148	            {
149	                coordDimensions: coordDimensions,
150	                dimensionsCount: defaultValueDimensions.length + 1,
151	                encodeDefaulter: zrUtil.curry(
152	                    makeSeriesEncodeForAxisCoordSys, coordDimensions, this as any
153	                )
154	            }
155	        );
156	    }
157	
158	    /**
159	     * If horizontal, base axis is x, otherwise y.
160	     * @override
161	     */
162	    getBaseAxis(): Axis2D {
163	        const dim = this._baseAxisDim;
164	        return (this.ecModel.getComponent(
165	            dim + 'Axis', this.get(dim + 'AxisIndex' as 'xAxisIndex' | 'yAxisIndex')
166	        ) as CartesianAxisModel).axis;
167	    }
168	
169	};
170	
171	
172	export {WhiskerBoxCommonMixin};
